<?php use App\Core\CSRF; $canOperate=$appointment['job_status']==='scheduled'&&in_array($appointment['status'],['confirmed','pending_confirmation'],true); ?>
<section class="container py-5" style="max-width:760px"><div class="card shadow-sm"><div class="card-body p-4"><h1 class="h3">Sua reserva</h1><?php if(!empty($message)):?><div class="alert alert-success"><?=htmlspecialchars($message)?></div><?php endif;?><dl class="row"><dt class="col-4">Estabelecimento</dt><dd class="col-8"><?=htmlspecialchars($appointment['tenant_name'])?></dd><dt class="col-4">Veículo</dt><dd class="col-8"><?=htmlspecialchars(trim(($appointment['make']??'').' '.$appointment['model'].' '.($appointment['plate']??'')))?></dd><dt class="col-4">Serviço</dt><dd class="col-8"><?=htmlspecialchars($appointment['service_name'])?></dd><dt class="col-4">Data</dt><dd class="col-8"><?=date('d/m/Y H:i',strtotime($appointment['starts_at']))?></dd><dt class="col-4">Box</dt><dd class="col-8"><?=htmlspecialchars($appointment['bay_name']??'A definir')?></dd><dt class="col-4">Status</dt><dd class="col-8"><?=htmlspecialchars($appointment['job_status'])?></dd></dl><?php if($canOperate):?><div class="d-flex flex-wrap gap-2"><?php if(!empty($settings['customer_can_reschedule'])):?><a class="btn btn-outline-primary" href="/auto/booking/<?=htmlspecialchars($token)?>/reschedule">Remarcar</a><?php endif;?><?php if(!empty($settings['customer_can_cancel'])):?><form method="post" action="/auto/booking/<?=htmlspecialchars($token)?>/cancel" onsubmit="return confirm('Cancelar esta reserva?')"><?=CSRF::field()?><button class="btn btn-outline-danger">Cancelar</button></form><?php endif;?></div><?php elseif(!in_array($appointment['status'],['cancelled','completed','no_show'],true)):?><div class="alert alert-info mb-0">O veículo já entrou no fluxo operacional. Alterações online não estão mais disponíveis; fale com o estabelecimento.</div><?php endif;?></div></div></section>
